<?php
require_once __DIR__.'/includes/db.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare("SELECT * FROM apps WHERE id=? AND status='published'");$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Không tìm thấy ứng dụng');}$s=db()->prepare("SELECT * FROM screenshots WHERE app_id=?");$s->execute([$id]);$imgs=$s->fetchAll();$pageTitle=$a['name'];require __DIR__.'/includes/header.php';?><a href="index.php">← Quay lại</a><section class="detail"><div class="appicon large"><?=e(mb_substr($a['name'],0,1))?></div><div><small><?=e($a['category'])?></small><h1><?=e($a['name'])?></h1><p><?=e($a['short_description'])?></p><?php if($a['download_url']):?><a class="btn" href="<?=e($a['download_url'])?>" target="_blank" rel="noopener">Tải ứng dụng</a><?php endif;?></div></section><article class="panel"><h2>Mô tả</h2><p><?=nl2br(e($a['description']))?></p><h2>Ảnh chụp màn hình</h2><div class="screens"><?php foreach($imgs as $im):?><img src="<?=e('uploads/screenshots/'.$im['filename'])?>" alt="<?=e($im['caption'])?>"><?php endforeach;?></div></article></main></body></html>